import numpy as np


def likelihood_displacement_curve(ts):
    ts = np.asarray(ts, dtype=np.float64)
    logits = np.stack([-ts, -3 * ts, 4 * ts], axis=1)
    logits -= logits.max(axis=1, keepdims=True)
    p = np.exp(logits); p /= p.sum(axis=1, keepdims=True)
    return {"t": ts, "chosen": p[:, 0], "rejected": p[:, 1], "other": p[:, 2], "log_margin": 2 * ts}


def displacement_alert(curve):
    return bool(np.all(np.diff(curve["log_margin"]) > 0) and np.mean(np.diff(np.log(curve["chosen"]))) < 0)
