import numpy as np


def dual_ascent_step(multipliers, expected_costs, limits, step_size):
    lam = np.asarray(multipliers, dtype=np.float64)
    costs = np.asarray(expected_costs, dtype=np.float64)
    bounds = np.asarray(limits, dtype=np.float64)
    if lam.shape != costs.shape or lam.shape != bounds.shape:
        raise ValueError("all arrays must have the same shape")
    if np.any(lam < 0) or not np.all(np.isfinite(lam)):
        raise ValueError("multipliers must be finite and non-negative")
    if step_size <= 0 or not np.isfinite(step_size):
        raise ValueError("step_size must be finite and positive")
    return np.maximum(0.0, lam + step_size * (costs - bounds))


def two_action_constrained_optimum(
    safe_reward,
    risky_reward,
    safe_cost,
    risky_cost,
    cost_limit,
):
    values = np.asarray(
        [safe_reward, risky_reward, safe_cost, risky_cost, cost_limit],
        dtype=np.float64,
    )
    if not np.all(np.isfinite(values)):
        raise ValueError("all inputs must be finite")
    if risky_cost <= safe_cost:
        raise ValueError("the teaching contract requires risky_cost > safe_cost")
    if cost_limit < safe_cost:
        raise ValueError("the cost budget is infeasible even for the safe action")
    q_max = np.clip(
        (cost_limit - safe_cost) / (risky_cost - safe_cost),
        0.0,
        1.0,
    )
    return float(q_max if risky_reward > safe_reward else 0.0)
